```js
// script.js — minimal playable snake (Ticket 1)

const GRID_SIZE = 20;
const TICK_MS = 150;
const CELL_PX = 24;

const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
canvas.width = GRID_SIZE * CELL_PX;
canvas.height = GRID_SIZE * CELL_PX;

const scoreEl = document.getElementById('score');
const overlayEl = document.getElementById('overlay');
const overlayTextEl = document.getElementById('overlay-text');
const playAgainBtn = document.getElementById('play-again');

// Game state (exposed on window for testing/debugging)
const state = {
  snake: [],       // array of {x, y}, head first
  dir: {x: 1, y: 0},
  nextDir: {x: 1, y: 0},
  food: null,
  score: 0,
  running: false,
  gameOver: false,
};

function resetGame() {
  const center = Math.floor(GRID_SIZE / 2);
  state.snake = [
    {x: center, y: center},
    {x: center - 1, y: center},
    {x: center - 2, y: center},
  ];
  state.dir = {x: 1, y: 0};
  state.nextDir = {x: 1, y: 0};
  state.score = 0;
  state.gameOver = false;
  spawnFood();
  updateScore();
}

function spawnFood() {
  const empty = [];
  const occupied = new Set(state.snake.map(s => s.x + ',' + s.y));
  for (let y = 0; y < GRID_SIZE; y++)
    for (let x = 0; x < GRID_SIZE; x++)
      if (!occupied.has(x + ',' + y)) empty.push({x, y});
  state.food = empty[Math.floor(Math.random() * empty.length)];
}

function setDirection(dx, dy) {
  // Ignore reversal: the new direction is invalid if it's the exact opposite of the current direction
  if (dx === -state.dir.x && dy === -state.dir.y) return;
  state.nextDir = {x: dx, y: dy};
}

function step() {
  if (!state.running) return;
  state.dir = state.nextDir;
  const head = state.snake[0];
  const nx = head.x + state.dir.x;
  const ny = head.y + state.dir.y;

  // Wall collision
  if (nx < 0 || ny < 0 || nx >= GRID_SIZE || ny >= GRID_SIZE) {
    endGame();
    return;
  }

  const willEat = state.food && nx === state.food.x && ny === state.food.y;

  // Self collision: if the tail moves away, check against the body excluding the tail cell (unless growing)
  const body = willEat ? state.snake : state.snake.slice(0, -1);
  if (body.some(seg => seg.x === nx && seg.y === ny)) {
    endGame();
    return;
  }

  state.snake.unshift({x: nx, y: ny});
  if (willEat) {
    state.score += 1;
    updateScore();
    spawnFood();
  } else {
    state.snake.pop();
  }
}
```

Wait — a detail on the self-collision check. When moving into a cell that the tail currently occupies but that tail cell will pop this tick (not eating), it's legal. My check: body = if not eating, the snake with the tail removed; if eating, the whole snake. This handles that.

Actually, standard behavior: when not eating, the tail moves, so moving into the current tail cell is fine. When eating, the tail doesn't move, so moving into the tail is a collision. My code handles this.

