function render() {
  // Background
  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Grid lines
  ctx.strokeStyle = 'rgba(255,255,255,0.07)';
  ctx.lineWidth = 1;
  for (let i = 1; i < GRID_SIZE; i++) {
    ctx.beginPath();
    ctx.moveTo(i * CELL_PX + 0.5, 0);
    ctx.lineTo(i * CELL_PX + 0.5, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * CELL_PX + 0.5);
    ctx.lineTo(canvas.width, i * CELL_PX + 0.5);
    ctx.stroke();
  }

  // Food
  if (state.food) {
    ctx.fillStyle = '#f44';
    const f = state.food;
    ctx.fillRect(f.x * CELL_PX + 2, f.y * CELL_PX + 2, CELL_PX - 4, CELL_PX - 4);
  }

  // Snake: head brighter
  state.snake.forEach((seg, i) => {
    ctx.fillStyle = i === 0 ? '#fff' : '#0f8';  // hmm, minimal colors
    ctx.fillRect(seg.x * CELL_PX + 1, seg.y * CELL_PX + 1, CELL_PX - 2, CELL_PX - 2);
  });
}
```

