Board sizing:

```js
// Largest board that fits the viewport while keeping cells >= MIN_CELL_PX.
function maxSizeForViewport() {
  const available = Math.min(window.innerWidth, window.innerHeight) - UI_CHROME_PX;
  return Math.max(MIN_SIZE, Math.floor(available / MIN_CELL_PX));
}

function computeBoardSize(requested) {
  let size = Math.round(Number(requested));
  if (!Number.isFinite(size)) size = DEFAULT_SIZE;
  size = Math.min(MAX_SIZE, Math.max(MIN_SIZE, size));
  return Math.min(size, maxSizeForViewport());
}

function cellSizeFor(size) {
  const available = Math.min(window.innerWidth, window.innerHeight) - UI_CHROME_PX;
  return Math.min(MAX_CELL_PX, Math.max(MIN_CELL_PX, Math.floor(available / size)));
}
