```js
function render() {
  const s = state.size;
  const px = state.cellPx;
  // Background.
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Faint grid lines.
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
  ctx.lineWidth = 1;
  for (let i = 1; i < s; i++) {
    ctx.beginPath();
    ctx.moveTo(i * px + 0.5, 0);
    ctx.lineTo(i * px + 0.5, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * px + 0.5);
    ctx.lineTo(canvas.width, i * px + 0.5);
    ctx.stroke();
  }

  // Food.
  if (state.food) {
    ctx.fillStyle = '#e33';
    ctx.fillRect(state.food.x * px + 2, state.food.y * px + 2, px - 4, px - 4);
  }

  // Snake: head in a distinct color, body in green.
  state.snake.forEach((p, i) => {
    ctx.fillStyle = i === 0 ? '#fff' : '#3c6';
    ctx.fillRect(p.x * px + 1, p.y * px + 1, px - 2, px - 2);
  });
}
```

