```js
// Snake — Ticket 2: start menu, "press any key" ready overlay,
// real-time score and session high score (no storage).
//
// Game logic is kept separate from rendering (see render()). State and
// controls are exposed on window.game so the loop can be stepped from
// scripts/tests.

const TICK_MS = 150;       // the snake advances one cell every tick
const DEFAULT_SIZE = 20;   // default board size (cells per side)
const MIN_SIZE = 10;       // smallest board the menu accepts
const MAX_SIZE = 99;       // largest board the menu accepts
const MIN_CELL_PX = 12;    // cells smaller than this would be unplayable
const MAX_CELL_PX = 32;    // keep cells from growing huge on big screens
const UI_CHROME_PX = 240;  // viewport reserved for HUD, hint and padding

// ---- DOM ----

const menuEl = document.getElementById('menu');
const gameScreenEl = document.getElementById('game-screen');
const sizeInput = document.getElementById('board-size');
const startBtn = document.getElementById('start-game');
const menuHighEl = document.getElementById('menu-high');

const scoreEl = document.getElementById('score');
const highEl = document.getElementById('high');
const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const readyOverlayEl = document.getElementById('ready-overlay');
const overOverlayEl = document.getElementById('over-overlay');
const finalScoreEl = document.getElementById('final-score');
const finalHighEl = document.getElementById('final-high');
const playAgainBtn = document.getElementById('play-again');

// ---- State ----

const state = {
  phase: 'menu',         // 'menu' | 'ready' | 'playing' | 'over'
  size: DEFAULT_SIZE,    // effective board size (cells per side)
  cellPx: 24,            // canvas pixels per cell
  snake: [],             // [{x, y}] cells, head first
  dir: { x: 1, y: 0 },   // current heading (applied each tick)
  nextDir: { x: 1, y: 0 },// latest valid input, applied on the next tick
  food: null,            // {x, y}
  score: 0,
};

// Session high score: in memory only, resets on page reload by design.
let sessionHigh = 0;
let loopTimer = null;

// ---- Board sizing ----

// Largest board that fits the viewport while keeping cells >= MIN_CELL_PX.
function maxSizeForViewport() {
  const available = Math.min(window.innerWidth, window.innerHeight) - UI_CHROME_PX;
  return Math.max(MIN_SIZE, Math.floor(available / MIN_CELL_PX));
}

// Clamp a requested size to [MIN_SIZE, MAX_SIZE], then to the viewport cap.
function computeBoardSize(requested) {
  let size = Math.round(Number(requested));
  if (!Number.isFinite(size)) size = DEFAULT_SIZE;
  size = Math.min(MAX_SIZE, Math.max(MIN_SIZE, size));
  return Math.min(size, maxSizeForViewport());
}

// Pixel size of one cell for a given board size, clamped to a sane range.
function cellSizeFor(size) {
  const available = Math.min(window.innerWidth, window.innerHeight) - UI_CHROME_PX;
  return Math.min(MAX_CELL_PX, Math.max(MIN_CELL_PX, Math.floor(available / size)));
}

// ---- Screens ----

function showMenu() {
  state.phase = 'menu';
  menuHighEl.textContent = String(sessionHigh);
  gameScreenEl.hidden = true;
  menuEl.hidden = false;
}

function showReady(size) {
  state.size = size;
  state.cellPx = cellSizeFor(size);
  canvas.width = state.size * state.cellPx;
  canvas.height = state.size * state.cellPx;
  resetGame();
  state.phase = 'ready';
  menuEl.hidden = true;
  gameScreenEl.hidden = false;
  readyOverlayEl.classList.add('visible');
  overOverlayEl.classList.remove('visible');
  render();
}

// Called by the "press any key" handler.
function startPlaying() {
  if (state.phase !== 'ready') return;
  state.phase = 'playing';
  readyOverlayEl.classList.remove('visible');
  startLoop();
}

// ---- Game control ----

function resetGame() {
  const c = Math.floor(state.size / 2);
  state.snake = [
    { x: c, y: c },
    { x: c - 1, y: c },
    { x: c - 2, y: c },
  ];
  state.dir = { x: 1, y: 0 };
  state.nextDir = { x: 1, y: 0 };
  state.score = 0;
  spawnFood();
  updateScore();
}

// Place food on a random cell that the snake does not occupy.
function spawnFood() {
  const occupied = new Set(state.snake.map((p) => p.x + ',' + p.y));
  const empty = [];
  for (let y = 0; y < state.size; y++) {
    for (let x = 0; x < state.size; x++) {
      if (!occupied.has(x + ',' + y)) empty.push({ x, y });
    }
  }
  state.food = empty[Math.floor(Math.random() * empty.length)];
}

function startLoop() {
  stopLoop();
  loopTimer = setInterval(step, TICK_MS);
}

function stopLoop() {
  if (loopTimer !== null) {
    clearInterval(loopTimer);
    loopTimer = null;
  }
}

function endGame() {
  state.phase = 'over';
  stopLoop();
  if (state.score > sessionHigh) sessionHigh = state.score;
  finalScoreEl.textContent = String(state.score);
  finalHighEl.textContent = String(sessionHigh);
  overOverlayEl.classList.add('visible');
  render();
}

// ---- Rules ----

function setDirection(dx, dy) {
  if (state.phase !== 'playing') return;
  // A 180-degree reversal is ignored; compare against nextDir so that two
  // valid turns pressed within the same tick are both allowed.
  if (dx === -state.nextDir.x && dy === -state.nextDir.y) return;
  state.nextDir = { x: dx, y: dy };
}

// Advance the game by one tick.
function step() {
  if (state.phase !== 'playing') return;

  state.dir = state.nextDir;
  const head = state.snake[0];
  const nx = head.x + state.dir.x;
  const ny = head.y + state.dir.y;

  // Wall collision.
  if (nx < 0 || ny < 0 || nx >= state.size || ny >= state.size) {
    endGame();
    return;
  }

  const eating = state.food.x === nx && state.food.y === ny;

  // Self collision. The tail cell is safe when it moves away this tick,
  // i.e. when the snake is not growing.
  const body = eating ? state.snake : state.snake.slice(0, -1);
  if (body.some((p) => p.x === nx && p.y === ny)) {
    endGame();
    return;
  }

  state.snake.unshift({ x: nx, y: ny });
  if (eating) {
    state.score += 1;
    if (state.score > sessionHigh) sessionHigh = state.score;
    updateScore();
    spawnFood();
  } else {
    state.snake.pop();
  }
  render();
}

// ---- Input ----

const KEY_DIRS = {
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 },
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
  w: { x: 0, y: -1 },
  s: { x: 0, y: 1 },
  a: { x: -1, y: 0 },
  d: { x: 1, y: 0 },
};

document.addEventListener('keydown', (e) => {
  // Any key dismisses the ready overlay and starts the run.
  if (state.phase === 'ready') startPlaying();
  if (state.phase !== 'playing') return;

  const key = e.key.length === 1 ? e.key.toLowerCase() : e.key;
  const d = KEY_DIRS[key];
  if (!d) {
    if (e.key === ' ') e.preventDefault(); // no page scroll on space
    return;
  }
  e.preventDefault();
  setDirection(d.x, d.y);
});

startBtn.addEventListener('click', () => {
  startBtn.blur(); // so Space/Enter cannot re-trigger the button mid-game
  showReady(computeBoardSize(sizeInput.value));
});

playAgainBtn.addEventListener('click', () => {
  playAgainBtn.blur();
  showMenu();
});

// ---- Rendering ----

function updateScore() {
  scoreEl.textContent = 'Score: ' + state.score;
  highEl.textContent = 'High: ' + sessionHigh;
}

function render() {
  const s = state.size;
  const px = state.cellPx;

  // Background.
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Faint grid lines.
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
  ctx.lineWidth = 1;
  for (let i = 1; i < s; i++) {
    ctx.beginPath();
    ctx.moveTo(i * px + 0.5, 0);
    ctx.lineTo(i * px + 0.5, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * px + 0.5);
    ctx.lineTo(canvas.width, i * px + 0.5);
    ctx.stroke();
  }

  // Food.
  if (state.food) {
    ctx.fillStyle = '#e33';
    ctx.fillRect(state.food.x * px + 2, state.food.y * px + 2, px - 4, px - 4);
  }

  // Snake: head in a distinct color, body in green.
  state.snake.forEach((p, i) => {
    ctx.fillStyle = i === 0 ? '#fff' : '#3c6';
    ctx.fillRect(p.x * px + 1, p.y * px + 1, px - 2, px - 2);
  });
}

// ---- Exposed for testing / debugging ----

window.game = {
  state,
  get sessionHigh() { return sessionHigh; },
  computeBoardSize,
  cellSizeFor,
  showMenu,
  showReady,
  startPlaying,
  resetGame,
  step,
  setDirection,
  spawnFood,
  startLoop,
  stopLoop,
  render,
  TICK_MS,
  MIN_SIZE,
  MAX_SIZE,
  MIN_CELL_PX,
  MAX_CELL_PX,
  UI_CHROME_PX,
};

// Start on the menu.
showMenu();
```

