```js
// Snake — neon edition.
//
// Modules:
//   Game     — pure game logic (state + rules). No DOM or canvas access.
//   Renderer — draws Game state onto a 2D canvas context (neon style).
//   App      — DOM wiring, keyboard input, animation loop.
//
// window.game exposes state + controls so the loop can be stepped from tests.

// ---- Config ----

const GRID_SIZE = 20; // cells per row/column
const TICK_MS = 150;  // snake advances one cell per tick
const CELL_PX = 24;   // logical canvas pixels per cell

// Neon palette (kept in one place, used by Renderer).
const NEON = {
  bg: '#020208',
  grid: 'rgba(0, 245, 255, 0.06)',
  snakeHead: '#d9fffb',
  snakeHeadGlow: '#00f5ff',
  snakeBody: [0, 245, 255],   // cyan at the head end
  snakeTail: [138, 92, 255],  // violet at the tail end
  food: '#ff2bd6',
  foodCore: '#ffffff',
};

// ---- Game: logic only ----

const Game = {
  snake: [],                // [{x, y}] cells, head first
  dir: { x: 1, y: 0 },      // current heading (applied each tick)
  nextDir: { x: 1, y: 0 },  // latest valid input, applied on the next tick
  food: null,               // {x, y}
  score: 0,
  gameOver: false,

  // Restore the initial state: length-3 snake at the center, heading right.
  reset() {
    const c = Math.floor(GRID_SIZE / 2);
    this.snake = [
      { x: c, y: c },
      { x: c - 1, y: c },
      { x: c - 2, y: c },
    ];
    this.dir = { x: 1, y: 0 };
    this.nextDir = { x: 1, y: 0 };
    this.score = 0;
    this.gameOver = false;
    this.spawnFood();
  },

  // Place food on a random cell the snake does not occupy.
  spawnFood() {
    const occupied = new Set(this.snake.map((p) => p.x + ',' + p.y));
    const empty = [];
    for (let y = 0; y < GRID_SIZE; y++) {
      for (let x = 0; x < GRID_SIZE; x++) {
        if (!occupied.has(x + ',' + y)) empty.push({ x, y });
      }
    }
    this.food = empty[Math.floor(Math.random() * empty.length)];
  },

  // Queue a new heading. 180-degree reversals are ignored; two valid turns
  // within the same tick are both allowed.
  setDirection(dx, dy) {
    if (this.gameOver) return;
    if (dx === -this.nextDir.x && dy === -this.nextDir.y) return;
    this.nextDir = { x: dx, y: dy };
  },

  // Advance the game by one tick.
  step() {
    if (this.gameOver) return;

    this.dir = this.nextDir;
    const head = this.snake[0];
    const nx = head.x + this.dir.x;
    const ny = head.y + this.dir.y;

    // Wall collision.
    if (nx < 0 || ny < 0 || nx >= GRID_SIZE || ny >= GRID_SIZE) {
      this.gameOver = true;
      return;
    }

    const eating = this.food.x === nx && this.food.y === ny;

    // Self collision. The tail cell is safe when it moves away this tick,
    // i.e. when the snake is not growing.
    const body = eating ? this.snake : this.snake.slice(0, -1);
    if (body.some((p) => p.x === nx && p.y === ny)) {
      this.gameOver = true;
      return;
    }

    this.snake.unshift({ x: nx, y: ny });
    if (eating) {
      this.score += 1;
      this.spawnFood();
    } else {
      this.snake.pop();
    }
  },
};
