// ---- Renderer: neon drawing on canvas ----

const Renderer = {
  canvas: null,
  ctx: null,
  dpr: 1,

  init(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    // Scale the backing store for sharp glow on hi-dpi screens.
    this.dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
    const size = GRID_SIZE * CELL_PX;
    canvas.width = size * this.dpr;
    canvas.height = size * this.dpr;
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  },

  // Full frame for the given game state; timeMs drives the food pulse.
  draw(state, timeMs) {
    const ctx = this.ctx;
    const size = GRID_SIZE * CELL_PX;

    // Background.
    ctx.shadowBlur = 0;
    ctx.fillStyle = NEON.bg;
    ctx.fillRect(0, 0, size, size);

    this.drawGrid(ctx);
    this.drawFood(ctx, state.food, timeMs);
    this.drawSnake(ctx, state.snake);
  },

  // Faint neon grid lines (single path, single stroke — cheap).
  drawGrid(ctx) {
    const size = GRID_SIZE * CELL_PX;
    ctx.save();
    ctx.strokeStyle = NEON.grid;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 1; i < GRID_SIZE; i++) {
      const p = i * CELL_PX + 0.5;
      ctx.moveTo(p, 0);
      ctx.lineTo(p, size);
      ctx.moveTo(0, p);
      ctx.lineTo(size, p);
    }
    ctx.stroke();
    ctx.restore();
  },

  // Food: magenta diamond with a pulsing glow.
  drawFood(ctx, food, timeMs) {
    if (!food) return;
    const cx = (food.x + 0.5) * CELL_PX;
    const cy = (food.y + 0.5) * CELL_PX;
    // Smooth 0 → 1 → 0 pulse with a ~900 ms period.
    const pulse = (1 - Math.cos((timeMs % 900) / 900 * Math.PI * 2)) / 2;
    const r = CELL_PX * (0.24 + 0.10 * pulse);

    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(Math.PI / 4); // square → diamond
    ctx.shadowColor = NEON.food;
    ctx.shadowBlur = 10 + 16 * pulse;
    ctx.fillStyle = NEON.food;
    ctx.fillRect(-r, -r, r * 2, r * 2);
    // Bright inner core.
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 0.6 + 0.4 * pulse;
    ctx.fillStyle = NEON.foodCore;
    const core = r * 0.42;
    ctx.fillRect(-core, -core, core * 2, core * 2);
    ctx.restore();
  },

  // Snake: rounded geometric blocks, cyan → violet gradient, neon glow.
  drawSnake(ctx, snake) {
    const n = snake.length;
    for (let i = n - 1; i >= 0; i--) {
      const p = snake[i];
      const head = i === 0;
      const t = n > 1 ? i / (n - 1) : 0; // 0 at head → 1 at tail
      const color = head
        ? NEON.snakeHead
        : mixNeon(NEON.snakeBody, NEON.snakeTail, t);
      const inset = head ? 1 : 2;
      const pad = inset; // hmm
      ...
    }
  },
};
