function stopLoop() {
  if (rafId !== null) {
    cancelAnimationFrame(rafId);
    rafId = null;
  }
}

// requestAnimationFrame frame: accumulate real time, run whole ticks of
// game logic, then draw once (the food pulse animates every frame).
function frame(now) {
  rafId = null;
  const dt = Math.min(now - lastFrame, 250); // clamp tab-switch jumps
  lastFrame = now;
  acc += dt;
  while (acc >= TICK_MS && !Game.gameOver) {
    acc -= TICK_MS;
    Game.step();
  }
  Renderer.draw(Game, now);
  if (Game.gameOver) {
    endGame();
    return; // board freezes on the final frame
  }
  rafId = requestAnimationFrame(frame);
}
