// Temporary self-test — steps the game with scripted inputs and asserts the
// rules. Prints one PASS/FAIL line. Remove before shipping.
(function () {
  const failures = [];
  function check(name, cond, sample) {
    if (!cond) failures.push(name + (sample ? ' :: ' + JSON.stringify(sample) : ''));
  }
  const g = window.game;
  const G = g.Game;

  g.stopLoop();

  // 1. Initial state.
  G.reset();
  check('reset: length 3', G.snake.length === 3, G.snake);
  check('reset: head at center', G.snake[0].x === 10 && G.snake[0].y === 10, G.snake[0]);
  check('reset: heading right', G.dir.x === 1 && G.dir.y === 0, G.dir);
  check('reset: food on board, not on snake',
    G.food && G.food.x >= 0 && G.food.x < 20 && G.food.y >= 0 && G.food.y < 20 &&
    !G.snake.some(p => p.x === G.food.x && p.y === G.food.y), G.food);

  // 2. Movement.
  G.step();
  check('move: head advanced right', G.snake[0].x === 11 && G.snake[0].y === 10, G.snake[0]);
  check('move: length unchanged', G.snake.length === 3, G.snake.length);

  // 3. Turning + reversal ignored.
  G.setDirection(0, -1);
  G.step();
  check('turn: head moved up', G.snake[0].y === 9 && G.snake[0].x === 11, G.snake[0]);
  G.setDirection(0, 1); // reversal while heading up → ignored
  check('turn: reversal ignored', G.nextDir.y === -1, G.nextDir);
  G.step();
  check('turn: still heading up', G.snake[0].y === 8, G.snake[0]);

  // 4. Eating grows + scores.
  G.food = { x: G.snake[0].x + G.dir.x, y: G.snake[0].y + G.dir.y };
  const scoreBefore = G.score;
  const lenBefore = G.snake.length;
  G.step();
  check('eat: score +1', G.score === scoreBefore + 1, G.score);
  check('eat: length +1', G.snake.length === lenBefore + 1, G.snake.length);
  check('eat: new food valid', G.food && !G.snake.some(p => p.x === G.food.x && p.y === G.food.y), G.food);

  // 5. Wall collision.
  G.snake = [{ x: 19, y: 5 }, { x: 18, y: 5 }, { x: 17, y: 5 }];
  G.dir = { x: 1, y: 0 }; G.nextDir = { x: 1, y: 0 };
  G.gameOver = false;
  G.step();
  check('wall: game over', G.gameOver === true, { head: G.snake[0] });

  // 6. Self collision.
  G.reset();
  G.snake = [{ x: 5, y: 5 }, { x: 4, y: 5 }, { x: 4, y: 6 }, { x: 5, y: 6 }, { x: 6, y: 6 }];
  G.dir = { x: -1, y: 0 }; G.nextDir = { x: -1, y: 0 };
  G.food = { x: 19, y: 19 };
  G.gameOver = false;
  G.step();
  check('self: game over', G.gameOver === true, { head: G.snake[0] });

  // 7. Chasing the tail (non-growing) is safe.
  G.reset();
  G.snake = [{ x: 5, y: 5 }, { x: 6, y: 5 }, { x: 6, y: 6 }, { x: 5, y: 6 }, { x: 4, y: 6 }];
  G.dir = { x: -1, y: 0 }; G.nextDir = { x: -1, y: 0 };
  G.food = { x: 19, y: 19 };
  G.gameOver = false;
  G.step();
  check('tail-chase: alive', G.gameOver === false, { head: G.snake[0] });
  check('tail-chase: head at (4,5)', G.snake[0].x === 4 && G.snake[0].y === 5, G.snake[0]);
  check('tail-chase: length 5', G.snake.length === 5, G.snake.length);

  // 8. Render smoke: draws without throwing and paints pixels.
  G.reset();
  G.gameOver = false;
  g.render(123);
  g.render(4567);
  const dpr = g.Renderer.dpr;
  const ctx = g.Renderer.ctx;
  function pxAt(cell) {
    const d = ctx.getImageData(
      Math.round((cell.x + 0.5) * g.CELL_PX * dpr),
      Math.round((cell.y + 0.5) * g.CELL_PX * dpr),
      1, 1).data;
    return d[0] + d[1] + d[2] > 40; // non-black
  }
  check('render: head pixel lit', pxAt(G.snake[0]));
  check('render: food pixel lit', pxAt(G.food));

  if (failures.length === 0) {
    console.log('SELFTEST PASS');
  } else {
    console.log('SELFTEST FAIL: ' + failures.join(' | '));
  }
  return failures.length === 0;
})();
